function premiumProfile(c,base){
 const distribution=order(c),hi=distribution[0][0],g=mg(c),b=branch(c),season=SEASON[c?.pillars?.month?.branch]||'';
 const hidden=c?.pillars?.day?.hidden||[],pg=(hidden.find(v=>v.role==='본기')||hidden[0])?.god||'';
 const weights={change:[],express:[],reflect:[],duty:[],precise:[],connect:[]},add=(key,ok,fact)=>{if(ok)weights[key].push(fact)};
 add('change',hi==='목','오행 상위 목');add('change',/비견|겁재|편재|상관/.test(g),'월간 '+g);add('change',['인','사','신'].includes(b),'일지 '+b);add('change',season==='봄','봄 월령');
 add('express',hi==='화','오행 상위 화');add('express',/식신|상관/.test(g),'월간 '+g);add('express',/식신|상관/.test(pg),'일지 본기 '+pg);add('express',season==='여름','여름 월령');
 add('reflect',hi==='수','오행 상위 수');add('reflect',/정인|편인/.test(g),'월간 '+g);add('reflect',/정인|편인/.test(pg),'일지 본기 '+pg);add('reflect',season==='겨울','겨울 월령');
 add('duty',hi==='토','오행 상위 토');add('duty',/정관|편관|정재/.test(g),'월간 '+g);add('duty',/정관|편관|정재/.test(pg),'일지 본기 '+pg);add('duty',['축','미','술'].includes(b),'일지 '+b);
 add('precise',hi==='금','오행 상위 금');add('precise',/상관|정관/.test(g),'월간 '+g);add('precise',/정관|정재/.test(pg),'일지 본기 '+pg);add('precise',season==='가을','가을 월령');
 add('connect',/편재|겁재/.test(g),'월간 '+g);add('connect',/목|화/.test(hi),'오행 상위 '+hi);add('connect',['인','신'].includes(b),'일지 '+b);add('connect',/편재|겁재/.test(pg),'일지 본기 '+pg);
 const ranked=Object.entries(weights).sort((a,b)=>b[1].length-a[1].length);
 // A single element never decides a mode; equal leading groups retain their contrast.
 const mode=ranked[0][1].length>=2&&ranked[0][1].length>ranked[1][1].length?ranked[0][0]:'balance';
 return {mode,v:PREMIUM_MODE[mode],hi,lo:distribution[4][0],g,pg,b,season,distribution,weights,base,
  support:mode==='balance'?ranked.slice(0,2).flatMap(r=>r[1]):weights[mode]};
}
